y Bebas Neue",sans-serif!important;letter-spacing:.04em!important;text-indent:0!important;text-transform:uppercase!important;box-shadow:none!important;cursor:pointer}.dizzy-table-picker-stage .dizzy-customer-table.round{border-radius:50%!important}.dizzy-table-picker-stage .dizzy-customer-table.booked{background:rgba(185,54,54,.5)!important;cursor:not-allowed}.dizzy-table-picker-stage .dizzy-customer-table.too_small{background:rgba(114,119,124,.5)!important;cursor:not-allowed}.dizzy-table-picker-stage .dizzy-customer-table.selected{background:rgba(217,144,0,.5)!important;box-shadow:0 0 0 4px rgba(255,185,0,.4)!important}.dizzy-table-legend{display:flex;gap:16px;flex-wrap:wrap;margin-top:10px;font-size:12px}.dizzy-table-legend i{display:inline-block;width:11px;height:11px;margin-right:5px;border-radius:50%}.dizzy-reservation-overlay{align-items:center;background:rgba(0,0,0,.82);display:none;inset:0;justify-content:center;padding:18px;position:fixed;z-index:999999}.dizzy-reservation-overlay.is-open{display:flex}.dizzy-reservation-modal{background:#191919;box-shadow:0 24px 70px rgba(0,0,0,.55);box-sizing:border-box;color:#fff;max-width:720px;padding:38px;position:relative;width:100%}.dizzy-reservation-close{appearance:none!important;background:transparent!important;border:0!important;box-shadow:none!important;color:#fff!important;font-size:28px!important;position:absolute;right:1px;top:1px}.dizzy-reservation-result{background:#1d1d1d;padding:24px}.dizzy-reservation-modal.is-success .dizzy-reservation-result{border-left:4px solid #46b450}.dizzy-reservation-modal.is-error .dizzy-reservation-result{border-left:4px solid #dc3232}@media(max-width:600px){.dizzy-table-picker-stage .dizzy-customer-table{font-size:13px!important}}
