        .dizzy-concert-choice[hidden]{display:none}.dizzy-concert-choice{padding:22px;border:1px solid var(--dr-border)}.dizzy-concert-choice h3{margin:0 0 7px;font-size:20px}.dizzy-concert-choice>p{margin:0 0 18px}.dizzy-experience-options{display:grid;gap:12px}.dizzy-experience-card{display:block!important;margin:0!important;padding:16px;border:1px solid var(--dr-border);cursor:pointer;letter-spacing:0!important;text-transform:none!important}.dizzy-experience-card:has(input:checked){border-color:#ffb900;box-shadow:inset 4px 0 #ffb900}.dizzy-experience-card strong,.dizzy-experience-card small{display:block;margin-left:26px}.dizzy-experience-card small{margin-top:4px;font-weight:400;line-height:1.5}.dizzy-ticket-options{display:grid;gap:8px;margin:12px 0 0 26px}.dizzy-ticket-options label{margin:0!important;letter-spacing:0!important;text-transform:none!important}.dizzy-ticket-choice-error{display:none;margin:10px 0 0 26px;color:#dc3232;font-weight:700}.dizzy-ticket-choice-error.is-visible{display:block}.dizzy-slot-summary{margin:16px 0 0;padding:12px;background:rgba(255,185,0,.12);line-height:1.55}.dizzy-ticket-buy-note{margin:8px 0 0;font-size:13px}
