        <div class="dizzy-reservation-field"><span class="dizzy-reservation-legend"><?php esc_html_e('Date','dizzy-reservations-manager'); ?>*</span><div class="dizzy-reservation-date-selects">
            <select name="reservation_day" aria-label="<?php esc_attr_e('Day','dizzy-reservations-manager'); ?>"><?php for($day=1;$day<=31;$day++): ?><option value="<?php echo esc_attr((string)$day); ?>" <?php selected($day,$todayDay); ?>><?php echo esc_html(sprintf('%02d',$day)); ?></option><?php endfor; ?></select>
