        <section class="dizzy-concert-choice" hidden aria-live="polite"><h3 class="dizzy-concert-title"></h3><p class="dizzy-concert-question"><?php esc_html_e('How would you like to spend your evening?','dizzy-reservations-manager'); ?></p><div class="dizzy-experience-options">
            <div class="dizzy-experience-card"><label><input type="radio" name="reservation_type" value="dinner_concert" checked><strong>🎷 <?php esc_html_e('Dinner + Concert','dizzy-reservations-manager'); ?></strong><small><?php esc_html_e('Dinner & Live Music — enjoy dinner before the show and keep your table for the entire concert.','dizzy-reservations-manager'); ?></small></label><span class="dizzy-ticket-options"><label><input type="radio" name="ticket_status" value="already_purchased"> 🎟 <?php esc_html_e('I already have concert tickets','dizzy-reservations-manager'); ?></label><label class="dizzy-buy-ticket"><input type="radio" name="ticket_status" value="buy"><span class="dizzy-buy-ticket-text"> <?php esc_html_e('Add concert tickets to my reservation','dizzy-reservations-manager'); ?></span></label></span><p class="dizzy-ticket-choice-error" role="alert"><?php esc_html_e('Please choose one of the concert ticket options above.','dizzy-reservations-manager'); ?></p></div>
            <label class="dizzy-experience-card"><input type="radio" name="reservation_type" value="dinner_only"><strong>🍽️ <?php esc_html_e('Dinner only','dizzy-reservations-manager'); ?></strong><small class="dizzy-dinner-only-copy"></small></label>
        </div><div class="dizzy-slot-summary"></div><p class="dizzy-ticket-buy-note" hidden></p></section>
        <?php if($hasTables): ?><div class="dizzy-reservation-field dizzy-table-picker" hidden><span class="dizzy-reservation-legend"><?php esc_html_e('Choose a table','dizzy-reservations-manager'); ?>*</span><p><?php esc_html_e('Select a green table. Click it again to deselect.','dizzy-reservations-manager'); ?></p><div class="dizzy-table-picker-stage" style="background-image:url('<?php echo esc_url($background); ?>')"></div><div class="dizzy-table-legend"><span><i style="background:#27935b"></i><?php esc_html_e('Available','dizzy-reservations-manager'); ?></span><span><i style="background:#b93636"></i><?php esc_html_e('Occupied','dizzy-reservations-manager'); ?></span><span><i style="background:#d99000"></i><?php esc_html_e('Selected','dizzy-reservations-manager'); ?></span></div></div><?php endif; ?>
        <p class="dizzy-reservation-field"><label for="dizzy-reservation-message"><?php esc_html_e('Your message','dizzy-reservations-manager'); ?>*</label><textarea id="dizzy-reservation-message" name="message" required></textarea></p><p><button class="dizzy-reservation-submit" type="submit"><?php esc_html_e('Send','dizzy-reservations-manager'); ?></button></p></form>
        <div class="dizzy-reservation-overlay" role="dialog" aria-modal="true" aria-hidden="true"><div class="dizzy-reservation-modal"><button type="button" class="dizzy-reservation-close">&times;</button><div class="dizzy-reservation-result" role="alert"></div></div></div></div>
        <script>
        (()=>{const shell=document.currentScript.previousElementSibling,form=shell.querySelector('form'),overlay=shell.querySelector('.dizzy-reservation-overlay'),modal=shell.querySelector('.dizzy-reservation-modal'),result=shell.querySelector('.dizzy-reservation-result'),close=shell.querySelector('.dizzy-reservation-close'),submit=form.querySelector('.dizzy-reservation-submit'),picker=form.querySelector('.dizzy-table-picker'),stage=form.querySelector('.dizzy-table-picker-stage'),tableId=form.querySelector('[name=table_id]'),reservationId=form.querySelector('[name=reservation_id]'),session=form.querySelector('[name=table_session]'),dateInput=form.querySelector('[name=reservation_date]'),dayInput=form.querySelector('[name=reservation_day]'),monthInput=form.querySelector('[name=reservation_month]'),yearInput=form.querySelector('[name=reservation_year]'),concertBox=form.querySelector('.dizzy-concert-choice'),concertTitle=form.querySelector('.dizzy-concert-title'),dinnerCopy=form.querySelector('.dizzy-dinner-only-copy'),slotSummary=form.querySelector('.dizzy-slot-summary'),choiceError=form.querySelector('.dizzy-ticket-choice-error'),buyNote=form.querySelector('.dizzy-ticket-buy-note'),buyText=form.querySelector('.dizzy-buy-ticket-text'),ajaxUrl=<?php echo wp_json_encode(admin_url('admin-ajax.php')); ?>,nonce=form.querySelector('[name=dizzy_reservation_nonce]').value,paymentState=<?php echo wp_json_encode($paymentState); ?>,storageKey='dizzyReservationCheckout';let loading=false,selected='',concert=null;
        const syncDate=()=>{const year=Number(yearInput.value),month=Number(monthInput.value),day=Number(dayInput.value),lastDay=new Date(year,month,0).getDate();if(day>lastDay)dayInput.value=String(lastDay);dateInput.value=year+'-'+String(month).padStart(2,'0')+'-'+String(dayInput.value).padStart(2,'0')};
        const vals=()=>({date:dateInput.value,time:form.querySelector('[name=reservation_time]:checked')?.value||'',guests:form.querySelector('[name=guests]').value,email:form.querySelector('[name=email]').value,reservation_type:form.querySelector('[name=reservation_type]:checked')?.value||'',ticket_status:form.querySelector('[name=ticket_status]:checked')?.value||''});const call=async(action,extra={})=>{const body=new FormData();body.set('action',action);body.set('dizzy_reservation_nonce',nonce);body.set('table_session',session.value);Object.entries({...vals(),...extra}).forEach(([k,v])=>body.set(k,v));const r=await fetch(ajaxUrl,{method:'POST',credentials:'same-origin',body}),j=await r.json();if(!j.success)throw new Error(j.data?.message||'Request failed');return j.data};
        const money=v=>new Intl.NumberFormat(undefined,{style:'currency',currency:'EUR'}).format(Number(v));
        async function refreshConcert(){const v=vals();if(!v.date||!v.time){concert=null;concertBox.hidden=true;return}try{concert=await call('dizzy_reservation_concert');if(!concert.has_concert){concertBox.hidden=true;return}concertBox.hidden=false;concertTitle.textContent=concert.date_label+' — '+concert.event_title+' at '+concert.concert_time;const dinnerInput=form.querySelector('[name=reservation_type][value=dinner_only]');dinnerInput.disabled=v.time>=concert.dinner_cutoff;if(dinnerInput.disabled&&dinnerInput.checked)form.querySelector('[name=reservation_type][value=dinner_concert]').checked=true;dinnerCopy.textContent=dinnerInput.disabled?'Dinner-only reservations are no longer available at this time.':'Your table is reserved until '+concert.dinner_cutoff+'. Concert admission is not included.';buyText.textContent=' Add concert tickets to my reservation ('+money(concert.ticket_price)+' per person)';const buying=form.querySelector('[name=ticket_status]:checked')?.value==='buy';buyNote.hidden=!buying;buyNote.textContent='After pressing Send, your table will be held while you complete secure payment with Mollie.';updateSummary()}catch(e){concert=null;concertBox.hidden=true}}
        function updateSummary(){if(!concert||!concert.has_concert)return;const type=form.querySelector('[name=reservation_type]:checked')?.value,ticket=form.querySelector('[name=ticket_status]:checked')?.value,time=vals().time,guests=Number(vals().guests||0);if(type==='dinner_only')slotSummary.textContent='Dinner reservation — '+time+'–'+concert.dinner_cutoff+'. A ticketed concert starts at '+concert.concert_time+'. This reservation does not include concert admission.';else if(!ticket)slotSummary.textContent='Please choose a concert ticket option.';else slotSummary.textContent='Dinner & Live Music — '+time+' through the concert. Your table remains yours for the show. '+(ticket==='already_purchased'?'We will verify your paid tickets using your reservation email address.':'Concert admission: '+guests+' × '+money(concert.ticket_price)+' = '+money(guests*Number(concert.ticket_price))+'.')}
        function draw(tables){stage.innerHTML='';tables.forEach(t=>{const b=document.createElement('button');b.type='button';b.className='dizzy-customer-table '+t.shape+' '+t.state+(String(t.id)===selected?' selected':'');b.textContent=t.code;b.disabled=t.state!=='available'&&String(t.id)!==selected;Object.assign(b.style,{left:t.pos_x+'%',top:t.pos_y+'%',width:t.width+'%',height:t.height+'%',transform:'rotate('+t.rotation+'deg)'});b.title=t.label+' · '+t.capacity+' people';b.onclick=async()=>{if(loading)return;loading=true;try{if(String(t.id)===selected){await call('dizzy_reservation_table_release');selected='';tableId.value=''}else{await call('dizzy_reservation_table_hold',{table_id:t.id});selected=String(t.id);tableId.value=t.id}await refresh(false)}catch(e){alert(e.message);selected='';tableId.value='';await refresh(false)}finally{loading=false}};stage.appendChild(b)})}
        async function refresh(clear=true){const v=vals();if(clear){selected='';tableId.value='';await call('dizzy_reservation_table_release').catch(()=>{})}await refreshConcert();const current=vals(),needsTicket=concert?.has_concert&&current.reservation_type==='dinner_concert'&&!current.ticket_status;choiceError.classList.toggle('is-visible',needsTicket);if(needsTicket){if(picker){picker.hidden=true;stage.innerHTML=''}return}if(!picker)return;if(!current.date||!current.time||!current.guests){picker.hidden=true;stage.innerHTML='';return}picker.hidden=false;try{draw((await call('dizzy_reservation_table_availability')).tables)}catch(e){stage.innerHTML='<span style="padding:12px;display:block">'+e.message+'</span>'}}form.querySelectorAll('[name=reservation_day],[name=reservation_month],[name=reservation_year]').forEach(x=>x.addEventListener('change',()=>{syncDate();refresh(true)}));form.querySelectorAll('[name=reservation_time],[name=guests],[name=reservation_type],[name=ticket_status]').forEach(x=>x.addEventListener('change',()=>{updateSummary();refresh(true)}));form.querySelector('[name=email]').addEventListener('change',()=>refresh(true));
        let validationStarted=false;const clearValidation=()=>{form.querySelectorAll('.wpcf7-not-valid-tip').forEach(t=>t.remove());form.querySelectorAll('[aria-invalid=true]').forEach(c=>c.removeAttribute('aria-invalid'))};
        const validateRequired=()=>{clearValidation();let first=null;const seen=new Set();form.querySelectorAll('[required]').forEach(control=>{if(seen.has(control.name))return;seen.add(control.name);const group=[...form.querySelectorAll('[name="'+CSS.escape(control.name)+'"]')],valid=control.type==='radio'?group.some(item=>item.checked):control.checkValidity();if(valid)return;first=first||control;group.forEach(item=>item.setAttribute('aria-invalid','true'));const field=control.closest('.dizzy-reservation-field')||control.parentElement,tip=document.createElement('span');tip.className='wpcf7-not-valid-tip';tip.setAttribute('aria-hidden','true');tip.textContent=control.validity.valueMissing?'The field is required.':control.validationMessage;field.appendChild(tip)});if(first){first.focus();return false}return true};
        form.addEventListener('input',e=>{if(validationStarted&&e.target.matches('[required]'))validateRequired()});form.addEventListener('change',e=>{if(validationStarted&&e.target.matches('[required]'))validateRequired()});
        const open=(m,ok)=>{result.innerHTML='<h2>'+(ok?'Reservation confirmed':'Reservation not confirmed')+'</h2><p></p>';result.querySelector('p').textContent=m;modal.classList.toggle('is-success',ok);modal.classList.toggle('is-error',!ok);overlay.classList.add('is-open')};close.onclick=()=>overlay.classList.remove('is-open');overlay.onclick=e=>{if(e.target===overlay)close.click()};
        const saveForm=id=>{const values={};new FormData(form).forEach((v,k)=>values[k]=String(v));values.reservation_id=String(id||reservationId.value||0);sessionStorage.setItem(storageKey,JSON.stringify(values))};const restoreForm=()=>{try{const values=JSON.parse(sessionStorage.getItem(storageKey)||'{}');Object.entries(values).forEach(([k,v])=>{const nodes=form.querySelectorAll('[name="'+CSS.escape(k)+'"]');nodes.forEach(node=>{if(node.type==='radio'||node.type==='checkbox')node.checked=node.value===v;else node.value=v})});selected=tableId.value;syncDate();return Number(reservationId.value)>0}catch(e){return false}};
        if(paymentState){if(paymentState==='paid'){sessionStorage.removeItem(storageKey);sessionStorage.removeItem(storageKey+'Polls');open('Payment received. Your reservation is confirmed and the confirmation email has been sent.',true)}else if(paymentState==='pending'){const polls=Number(sessionStorage.getItem(storageKey+'Polls')||0);open('Your payment is still being processed. Please wait; this page will check again automatically.',false);if(polls<4){sessionStorage.setItem(storageKey+'Polls',String(polls+1));setTimeout(()=>location.reload(),3000)}}else{sessionStorage.removeItem(storageKey+'Polls');const restored=restoreForm();open(restored?'Payment was not completed. Your reservation details are saved; press Send to try payment again.':'Payment was not completed. Please review the form and try again.',false);refresh(false)}}
        form.onsubmit=async e=>{e.preventDefault();validationStarted=true;if(!validateRequired())return;if(picker&&!tableId.value&&Number(reservationId.value)<1){open('Please select an available table.',false);return}submit.disabled=true;form.querySelector('[name=return_url]').value=location.origin+location.pathname;const body=new FormData(form);body.set('action','dizzy_reservation_submit');try{const r=await fetch(ajaxUrl,{method:'POST',credentials:'same-origin',body}),j=await r.json();if(!j.success){if(j.data?.reservation_id){reservationId.value=j.data.reservation_id;saveForm(j.data.reservation_id)}throw new Error(j.data?.message||'Reservation could not be completed.')}if(j.data.redirect_url){reservationId.value=j.data.reservation_id;saveForm(j.data.reservation_id);location.assign(j.data.redirect_url);return}sessionStorage.removeItem(storageKey);form.reset();validationStarted=false;clearValidation();form.querySelector('[name=guests]').value='2';selected='';concert=null;concertBox.hidden=true;tableId.value='';if(picker)picker.hidden=true;open(j.data.message,true)}catch(err){open(err.message||'Reservation could not be completed.',false)}finally{submit.disabled=false}}})();
        </script><?php return(string)ob_get_clean();
    }
    public function ajaxConcert():void{$this->verify();try{[$d,$t,$g]=$this->requestData(false);$plan=$this->service->plan($d,$t,$g,'dinner_concert','already_purchased');$plan['date_label']=wp_date('l j F',strtotime($d));wp_send_json_success($plan);}catch(Throwable $e){wp_send_json_error(['message'=>$e->getMessage()],400);}}
    public function ajaxAvailability():void{$this->verify();try{[$d,$t,$g,$s]=$this->requestData();$plan=$this->service->plan($d,$t,$g,sanitize_key((string)($_POST['reservation_type']??'')),sanitize_key((string)($_POST['ticket_status']??'')),sanitize_email((string)($_POST['email']??'')));wp_send_json_success(['tables'=>$this->tables->availability($d,$t,$g,$s,$plan['duration_minutes'])]);}catch(Throwable $e){wp_send_json_error(['message'=>$e->getMessage()],400);}}
    public function ajaxHold():void{$this->verify();try{[$d,$t,$g,$s]=$this->requestData();$plan=$this->service->plan($d,$t,$g,sanitize_key((string)($_POST['reservation_type']??'')),sanitize_key((string)($_POST['ticket_status']??'')),sanitize_email((string)($_POST['email']??'')));$id=absint($_POST['table_id']??0);if($id<1||!$this->tables->hold($id,$d,$t,$g,$s,$plan['duration_minutes']))wp_send_json_error(['message'=>__('That table is no longer available. Please choose another table.','dizzy-reservations-manager')],409);wp_send_json_success();}catch(Throwable $e){wp_send_json_error(['message'=>$e->getMessage()],400);}}
    public function ajaxRelease():void{$this->verify();$s=sanitize_key((string)($_POST['table_session']??''));if($s!=='')$this->tables->release($s);wp_send_json_success();}
    public function ajaxSubmit():void{$this->verify();$id=absint($_POST['reservation_id']??0);try{if($id<1)$id=$this->service->create(wp_unslash($_POST));$row=$this->service->reservation($id);if(($row['status']??'')==='pending_payment'||($row['status']??'')==='payment_failed'){$checkout=$this->service->startPayment($id,esc_url_raw((string)($_POST['return_url']??'')),sanitize_email((string)($_POST['email']??'')));wp_send_json_success(['reservation_id'=>$id,'redirect_url'=>(string)$checkout['checkout_url']]);}wp_send_json_success(['reservation_id'=>$id,'message'=>__('Your reservation is confirmed. A confirmation email has been sent.','dizzy-reservations-manager')]);}catch(Throwable $e){error_log('Dizzy AJAX reservation failed: '.$e->getMessage());wp_send_json_error(['reservation_id'=>$id,'message'=>$e->getMessage()],400);}}
    public function submit():void{if(($_SERVER['REQUEST_METHOD']??'')!=='POST'||!isset($_POST['dizzy_reservation_submit']))return;$this->verify();try{$id=$this->service->create(wp_unslash($_POST));$row=$this->service->reservation($id);if(($row['status']??'')==='pending_payment'){$checkout=$this->service->startPayment($id,wp_get_referer()?:home_url('/'),(string)($row['email']??''));wp_redirect((string)$checkout['checkout_url'],303,'Dizzy Reservations');exit;}$r='success';}catch(Throwable $e){$r='error';}wp_safe_redirect(add_query_arg('reservation',$r,wp_get_referer()?:home_url('/')));exit;}
    private function requestData(bool $requireSession=true):array{$d=sanitize_text_field((string)($_POST['date']??''));$t=sanitize_text_field((string)($_POST['time']??''));$g=absint($_POST['guests']??0);$s=sanitize_key((string)($_POST['table_session']??''));$p=\DateTimeImmutable::createFromFormat('!Y-m-d',$d,wp_timezone());if(!$p||$p<new \DateTimeImmutable('today',wp_timezone())||!in_array($t,ReservationService::TIMES,true)||$g<1||$g>100||($requireSession&&$s===''))wp_send_json_error(['message'=>__('Choose a valid date, time and guest count.','dizzy-reservations-manager')],400);return[$d,$t,$g,$s];}
    private function verify():void{$n=sanitize_text_field(wp_unslash((string)($_POST['dizzy_reservation_nonce']??'')));if(!wp_verify_nonce($n,'dizzy_reservation_submit'))wp_send_json_error(['message'=>__('Your session expired. Refresh the page and try again.','dizzy-reservations-manager')],403);}
    private function field(string $n,string $l,string $t,string $a):void{echo'<p class="dizzy-reservation-field"><label for="dizzy-reservation-'.esc_attr($n).'">'.esc_html($l).'*</label><input id="dizzy-reservation-'.esc_attr($n).'" type="'.esc_attr($t).'" name="'.esc_attr($n).'" autocomplete="'.esc_attr($a).'" required></p>';}
}
